namespace ckernel::sfpu::SoftsignBwBf16Config_initialization {
namespace sfpi = ::ckernel::sfpu::SoftsignBwBf16Config_detail;
inline void init() {
#if defined(TRISC_MATH)
    ckernel::llk_math_sfpu_init_once();
#endif
    ckernel::sfpu::sfpu_reciprocal_init<false>();
    ckernel::addr_mod_t{
        .srca = {.incr = 0},
        .srcb = {.incr = 0},
        .dest = {.incr = 2},
    }
        .set(ckernel::ADDR_MOD_6);
}
}  // namespace ckernel::sfpu::SoftsignBwBf16Config_initialization
